-- =====================================================================
-- DML - Modulo de actividades extracurriculares: clubes (datos de prueba ficticios)
-- 34 clubes (32 activos y 2 cerrados), cada uno con su profesor encargado, cupo y horario.
-- Casos de prueba para la inscripcion y el cupo:
--   Club de Ajedrez (cupo 6) y Club de Teatro (cupo 8) estan LLENOS; Club de Robotica (cupo 10) tiene 1 cupo libre.
--   David Arango (id 3) esta activo en varios clubes; Thomas Cortes (id 18) salio del Club de Ciencias y volvio a entrar.
--   Los clubes cerrados (Origami, Radio Escolar) solo tienen membresias retiradas, y hay retiros de estudiantes egresados.
-- Los id_club salen del orden de insercion de esta misma sentencia (1 = Club de Ciencias, ...).
-- =====================================================================

