-- =====================================================================
-- DML - Modulo de actividades extracurriculares: eventos (datos de prueba ficticios)
-- 25 eventos de los 4 tipos entre 2025 y diciembre de 2026: 3 proximos, 1 cancelado y el resto ya realizados.
-- Los eventos con competencia guardan la posicion de cada participante (1er, 2do, 3er Lugar o Participante);
-- los demas guardan la posicion en NULL.
-- Casos de prueba:
--   Feria del Libro (2026-11-13): realizado, sin competencia y sin participantes (sirve para registrar participantes).
--   Torneo de Voleibol (2026-11-06): con competencia; todos son Participante (sirve para asignar posiciones).
--   Campeonato Interclases de Futbol: competencia por equipos, varios estudiantes comparten cada posicion.
--   David Arango (id 3) fue 1er Lugar en la Feria de Ciencias 2026; el estudiante id 40 no ha participado en ninguno.
-- Los id_evento salen del orden de insercion de esta misma sentencia (1 = Dia del Idioma 2025, ...).
-- =====================================================================

